import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';

import '../storage/app_store.dart';

/// Every sound cue in the app. File names match `assets/audio/<name>.wav`,
/// generated by `tool/gen_sfx.py`.
enum Sfx {
  tap,
  select,
  place,
  move,
  capture,
  flip,
  dice,
  hop,
  fly,
  merge,
  clear,
  star,
  error,
  win,
  lose,
  tick,
  go,
  eat,
  whack,
  pop,
  flap,
  crash,
  check,
  slide,
  bomb,
  combo,
  undo,
  hint,
  unlock,
  turn,
  coinSlot,
  coinContact,
  coinTray,
  pusherMotor;

  String get asset => 'audio/$name.wav';
}

/// Plays short cues through a small round-robin pool of players plus one
/// looping background-music player.
///
/// Audio is decorative: every failure is swallowed so a broken audio backend
/// can never break a game.
class SoundService with WidgetsBindingObserver {
  SoundService._();

  static final SoundService instance = SoundService._();

  static const _poolSize = 6;
  static const _musicVolume = 0.28;

  final List<AudioPlayer> _pool = [];
  int _next = 0;
  AudioPlayer? _music;
  bool _musicPlaying = false;
  bool _foreground = true;
  bool _ready = false;

  Future<void> init() async {
    WidgetsBinding.instance.addObserver(this);
    AppStore.instance.addListener(_syncMusic);
    try {
      // Never awaited: the ohos plugin applies the context but never replies
      // to this call, so awaiting it would hang init forever and leave every
      // cue silent.
      unawaited(AudioPlayer.global
          .setAudioContext(
        const AudioContext(
          iOS: AudioContextIOS(
            category: AVAudioSessionCategory.ambient,
            options: [AVAudioSessionOptions.mixWithOthers],
          ),
          // The ohos default is a music stream that keeps the screen awake and
          // takes exclusive audio focus, so every new cue cut off the previous
          // one and the BGM. Game-usage streams are mixed instead.
          ohos: AudioContextOhos(
            isSpeakerphoneOn: false,
            stayAwake: false,
            usageType: OhosUsageType.game,
          ),
          android: AudioContextAndroid(
            isSpeakerphoneOn: false,
            stayAwake: false,
            contentType: AndroidContentType.sonification,
            usageType: AndroidUsageType.game,
            audioFocus: AndroidAudioFocus.none,
          ),
        ),
      )
          .catchError((Object error) {
        debugPrint('SoundService: audio context unavailable: $error');
      }));
    } catch (error) {
      debugPrint('SoundService: audio context unavailable: $error');
    }
    try {
      for (var i = 0; i < _poolSize; i++) {
        final player = AudioPlayer();
        await player.setReleaseMode(ReleaseMode.stop);
        _pool.add(player);
      }
      // Playing works without the preload (it only avoids first-play lag), so
      // a preload failure must never silence the whole app.
      _ready = true;
    } catch (error) {
      debugPrint('SoundService: init failed: $error');
    }
    if (_ready && !kIsWeb) unawaited(_preload());
    _syncMusic();
  }

  Future<void> _preload() async {
    for (final cue in Sfx.values) {
      try {
        await AudioCache.instance.load(cue.asset);
      } catch (error) {
        debugPrint('SoundService: preload ${cue.name} failed: $error');
      }
    }
    try {
      await AudioCache.instance.load('audio/bgm.wav');
    } catch (error) {
      debugPrint('SoundService: preload bgm failed: $error');
    }
  }

  void play(Sfx cue, {double volume = 1.0}) {
    if (!_ready || !AppStore.instance.soundOn) return;
    final player = _pool[_next];
    _next = (_next + 1) % _pool.length;
    unawaited(_start(player, cue, volume));
  }

  Future<void> _start(AudioPlayer player, Sfx cue, double volume) async {
    try {
      await player.play(AssetSource(cue.asset),
          volume: volume * AppStore.instance.volume);
    } catch (error) {
      debugPrint('SoundService: failed to play ${cue.name}: $error');
      await _replace(player);
    }
  }

  /// A player stuck in a bad native state would stay silent forever; swap it
  /// for a fresh one.
  Future<void> _replace(AudioPlayer broken) async {
    final index = _pool.indexOf(broken);
    if (index < 0) return;
    try {
      final fresh = AudioPlayer();
      await fresh.setReleaseMode(ReleaseMode.stop);
      _pool[index] = fresh;
      unawaited(broken.dispose());
    } catch (error) {
      debugPrint('SoundService: could not replace player: $error');
    }
  }

  void _syncMusic() {
    if (!_ready) return;
    if (_musicPlaying) unawaited(_applyMusicVolume());
    final want = AppStore.instance.musicOn && _foreground;
    if (want == _musicPlaying) return;
    _musicPlaying = want;
    unawaited(want ? _startMusic() : _stopMusic());
  }

  Future<void> _startMusic() async {
    try {
      final music = _music ??= AudioPlayer();
      await music.setReleaseMode(ReleaseMode.loop);
      await music.play(AssetSource('audio/bgm.wav'),
          volume: _musicVolume * AppStore.instance.volume);
    } catch (error) {
      debugPrint('SoundService: music failed: $error');
    }
  }

  Future<void> _applyMusicVolume() async {
    try {
      await _music?.setVolume(_musicVolume * AppStore.instance.volume);
    } catch (error) {
      debugPrint('SoundService: music volume failed: $error');
    }
  }

  Future<void> _stopMusic() async {
    try {
      await _music?.pause();
    } catch (error) {
      debugPrint('SoundService: music pause failed: $error');
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _foreground = state == AppLifecycleState.resumed;
    _syncMusic();
  }
}
